// Generated from src/registry/sources/control-ui/recipes/field.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const fieldKnobs = [
  "--cui-field-radius",
  "--cui-field-background",
  "--cui-field-foreground",
  "--cui-field-border-color",
  "--cui-field-border-width",
  "--cui-field-shadow",
  "--cui-field-backdrop-filter",
  "--cui-field-focus-border-color",
] as const;
export type FieldKnobStyle = Partial<Record<(typeof fieldKnobs)[number], string>>;

@layer components {
  :where([data-control-family="field"][data-field-kind="input-group"][data-slot="addon"]),
  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]),
  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]),
  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]),
  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]),
  :where([data-control-family="field"][data-field-kind="native-select"][data-slot="icon"]) {
    color: var(--muted-foreground);
  }

  :where([data-control-family="field"][data-field-kind="input-group"][data-slot="input"]),
  :where([data-control-family="field"][data-field-kind="phone-input"][data-slot="input"]),
  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"]) {
    outline: none;
    background: transparent;
    color: var(--foreground);
  }

  :where([data-control-family="field"][data-field-kind="input-group"][data-slot="input"])::placeholder,
  :where([data-control-family="field"][data-field-kind="phone-input"][data-slot="input"])::placeholder,
  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"])::placeholder {
    color: var(--muted-foreground);
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]),
  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]) {
    border-radius: var(--radius-control);
    outline: none;
    transition-property: color, box-shadow;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  @media (hover: hover) {
    :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]:hover),
    :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]:hover),
    :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]:hover),
    :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]:hover) {
      color: var(--foreground);
    }
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="trigger"]:disabled),
  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="clear"]:disabled) {
    cursor: not-allowed;
    opacity: 0.45;
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="icon"]) {
    transition-property: rotate;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where(
    [data-control-family="field"][data-field-kind="combobox"][data-popup-open]
      :where([data-control-family="field"][data-field-kind="combobox"][data-slot="icon"])
  ) {
    rotate: 180deg;
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]) {
    border-inline-end: 1px solid var(--border);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]) {
    border-inline-start: 1px solid var(--border);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]),
  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]) {
    outline: none;
    transition-property: color, background-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"]:active),
  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"]:active) {
    background: oklch(from var(--foreground) l c h / 0.06);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="decrement"][data-disabled]),
  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="increment"][data-disabled]) {
    color: oklch(from var(--muted-foreground) l c h / 0.5);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="scrub-cursor"]) {
    color: var(--foreground);
    filter: drop-shadow(0 1px 1px oklch(0 0 0 / 0.05));
  }

  :where([data-control-family="field"][data-field-kind="input-otp"][data-slot="root"]) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="field"][data-field-kind="input-otp"][data-slot="separator"]) {
    block-size: 1px;
    inline-size: calc(var(--spacing) * 2.5);
    border-radius: 9999px;
    background: var(--border);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="title"]) {
    color: var(--foreground);
    font-size: var(--text-label);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="label"]) {
    color: var(--foreground);
    font-size: var(--text-label);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="label"][data-disabled]) {
    opacity: 0.5;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-caption);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="error"]) {
    color: var(--destructive-text);
    font-size: var(--text-caption);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="separator"]) {
    font-size: var(--text-caption);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="separator-content"]) {
    background-color: var(--background);
    color: var(--muted-foreground);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="set"]) {
    border-width: 0px;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="legend"]) {
    color: var(--foreground);
    font-size: var(--text-label);
    font-weight: var(--font-weight-semibold);
  }
}

@layer components {
  :where([data-control-family="field"][data-control="true"]) {
    gap: calc(var(--spacing) * 1.5);
    --cui-field-radius: var(--radius-control);
    --cui-field-background: oklch(from var(--card) l c h / 0.72);
    --cui-field-foreground: var(--foreground);
    --cui-field-border-color: var(--border);
    --cui-field-border-width: 1px;
    --cui-field-shadow: var(--shadow-sm);
    --cui-field-backdrop-filter: blur(0px);
    --cui-field-focus-border-color: var(--border);
    border: var(--cui-field-border-width) solid var(--cui-field-border-color);
    border-radius: var(--cui-field-radius);
    outline: none;
    background: var(--cui-field-background);
    box-shadow: var(--cui-field-shadow);
    color: var(--cui-field-foreground);
    backdrop-filter: var(--cui-field-backdrop-filter);
  }

  :where(
    [data-control-family="field"][data-control="true"]:not([data-control-family="field"][data-field-kind="autocomplete"]):not(
      [data-control-family="field"][data-field-kind="combobox"]
    )
  ) {
    transition-property: color, background-color, border-color, box-shadow, opacity, backdrop-filter;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="field"][data-control="true"][data-size="xs"]) {
    gap: calc(var(--spacing) * 1);
  }
  :where([data-control-family="field"][data-control="true"][data-size="lg"]) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="field"][data-control="true"])::placeholder {
    color: var(--muted-foreground);
  }

  @media (hover: hover) {
    :where([data-control-family="field"][data-field-kind="autocomplete"]:hover),
    :where([data-control-family="field"][data-field-kind="combobox"]:hover),
    :where([data-control-family="field"][data-field-kind="native-select"]:hover),
    :where([data-control-family="field"][data-field-kind="number-field"]:hover) {
      background: oklch(from var(--foreground) l c h / 0.05);
    }
  }

  :where([data-control-family="field"][data-control="true"]:is(:focus-visible, :focus-within)) {
    border-color: var(--cui-field-focus-border-color);
  }

  :where([data-control-family="field"][data-control="true"][data-invalid]),
  :where([data-control-family="field"][data-control="true"][aria-invalid="true"]) {
    box-shadow:
      0 0 0 2px var(--destructive),
      var(--cui-field-shadow);
  }

  :where([data-control-family="field"][data-control="true"]:disabled),
  :where([data-control-family="field"][data-control="true"][data-disabled]) {
    cursor: not-allowed;
    opacity: 0.5;
  }

  :where([data-control-family="field"][data-field-kind="input-otp"][data-slot="slot"]) {
    text-align: center;
    font-size: var(--text-body);
    font-weight: var(--font-weight-medium);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="input"]) {
    padding-inline-end: calc(var(--spacing) * 9);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="native-select"][data-slot="root"]) {
    font-weight: var(--font-weight-medium);
    appearance: none;
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="drag-icon"]) {
    color: var(--foreground);
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="input"]) {
    padding-inline: calc(var(--spacing) * 2);
    text-align: center;
    font-weight: var(--font-weight-medium);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="field"][data-field-kind="number-field"][data-slot="group"]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="textarea"][data-slot="root"]) {
    min-block-size: calc(var(--spacing) * 16);
    max-block-size: calc(var(--spacing) * 64);
    padding: calc(var(--spacing) * 2) calc(var(--spacing) * 3);
    font-size: var(--text-body);
  }

  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="input"]) {
    padding-inline-end: calc(var(--spacing) * 9);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="root"]) {
    gap: calc(var(--spacing) * 3);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="content"]) {
    gap: calc(var(--spacing) * 1);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="group"]),
  :where([data-control-family="field"][data-field-kind="form"][data-slot="root"]) {
    gap: calc(var(--spacing) * 5);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="item"]) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="set"]) {
    gap: calc(var(--spacing) * 4);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="separator"]) {
    block-size: 1px;
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="separator"][data-content]) {
    margin-block: calc(var(--spacing) * 2);
    block-size: calc(var(--spacing) * 5);
  }

  :where([data-control-family="field"][data-field-kind="field"][data-slot="separator-content"]) {
    margin-inline: auto;
    padding-inline: calc(var(--spacing) * 2);
  }

  :where([data-control-family="field"][data-field-kind="phone-input"][data-slot="input"]) {
    padding-inline: calc(var(--spacing) * 3);
  }
}

@property --cui-field-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-field-background {
  syntax: "*";
  inherits: true;
}

@property --cui-field-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-field-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-field-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-field-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-field-backdrop-filter {
  syntax: "*";
  inherits: true;
}

@property --cui-field-focus-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

import type { ComponentProps, CSSProperties } from "react";
import type { ControlSize } from "@/components/control-ui/control-variants";
import { controlSize } from "@/components/control-ui/control-variants";
import type { FieldKnobStyle } from "@/components/control-ui/knob-contracts/field-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type NativeSelectProps = Omit<Omit<ComponentProps<"select">, "size">, "style"> & { style?: CSSProperties & FieldKnobStyle } & {
  size?: ControlSize;
};

// real native <select>, not floating Base UI Select — its options open OS menu, so nothing portals and no scope is re-asserted.
export function NativeSelect({ size = "md", className, children, ...props }: NativeSelectProps) {
  return (
    <div className="relative inline-flex w-full items-center">
      <select
        data-control-ui="native-select"
        data-field-kind="native-select"
        data-slot="root"
        data-size={size}
        data-control-family="field"
        data-control="true"
        className={cn("w-full min-w-0 cursor-pointer pr-[calc(var(--padding-x)*1.4)]", controlSize({ size }), className)}
        {...props}
      >
        {children}
      </select>
      <span
        aria-hidden="true"
        data-control-ui="native-select"
        data-control-family="field"
        data-field-kind="native-select"
        data-slot="icon"
        className="pointer-events-none absolute right-[calc(var(--padding-x)*0.6)]"
      >
        <svg viewBox="0 0 12 12" className="size-3" aria-hidden="true" fill="none">
          <path d="M3 4.5 6 7.5 9 4.5" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </span>
    </div>
  );
}
